#include <bits/stdc++.h>
using namespace std;
const int MOD = 998244353;
int n;
bool ok(int i,int x, int l, bool left){
    int r = x - l;
    int pos = left ? l : n - r + 1;
    if(pos <= i && min(i, l) + max(0, i - n + r) == (i + 1) / 2) return true;
    if(pos >= i && min(r, n - i + 1) + max(0, l - i + 1) == (n - i + 2) / 2) return true;
    return false;
}
int main() {
	int t;
	cin>>t;
	while(t--){
	    cin>>n;
	    vector<vector<int>> byv(n + 1);
	    for(int i = 1; i <= n; i++){
	        int a;
	        cin>>a;
	        byv[a].push_back(i);
	        
	    }
	    vector<long long> tot(n + 2, 0), nl(n + 2), nr(n + 2);
	    tot[0] = 1;
	    for(int x = 1; x <= n; x++){
	        fill(nl.begin(), nl.end(), 0);
	        fill(nr.begin(), nr.end(), 0);
	        for(int lp = 0; lp <=x - 1; lp++){
	            long long w = tot[lp];
	            if(!w) continue;
	            nl[lp + 1] = (nl[lp + 1] + w) % MOD;
	            if(x < n) nr[lp] = (nr[lp] + w) % MOD;
	        }
	        for(int l = 0; l <= x; l++){
	            if(nl[l])
	                for(int i : byv[x])
	                    if(!ok(i, x, l, true)){nl[l] = 0; break;}
	                
	           if(nr[l])
	               for(int i : byv[x])
	                   if(!ok(i, x, l, false)) {nr[l] = 0; break;}
	               
	           tot[l] = (nl[l] + nr[l]) % MOD;
	        }
	           
	            tot[x + 1] = 0;
	        }
	        long long ans = 0;
	        for(int i = 0; i <= n; i++) ans += tot[i];
	        cout<<ans % MOD<<endl;
	    }
	}
